import org.neo4j.ogm.annotation.GeneratedValue;
import org.neo4j.ogm.annotation.Id;
import org.neo4j.ogm.annotation.NodeEntity;
import org.neo4j.ogm.annotation.Relationship;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;

@NodeEntity( label = "Car" )
public class Car {

  @GeneratedValue
  @Id
  private Long id;

  @JsonIgnoreProperties( { "car" } )
  @Relationship( type = "DRIVEN_BY", direction = Relationship.OUTGOING )
  private CarDriver drivenBy;

  public Long getId()
  {
    return this.id;
  }

  public CarDriver getDrivenBy()
  {
    return this.drivenBy;
  }

  public void setDrivenBy( final CarDriver value )
  {
    if( this.drivenBy != null && this.drivenBy.getCar() != this )
    {
      this.drivenBy.setCar( null );
    }
    this.drivenBy = value;
    if( this.drivenBy != null && this.drivenBy.getCar() != this )
    {
      this.drivenBy.setCar( this );
    }
  }
}
