import org.neo4j.ogm.annotation.EndNode;
import org.neo4j.ogm.annotation.GeneratedValue;
import org.neo4j.ogm.annotation.Id;
import org.neo4j.ogm.annotation.RelationshipEntity;
import org.neo4j.ogm.annotation.StartNode;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;

@RelationshipEntity( type = "DRIVEN_BY" )
public class CarDriver {
  @GeneratedValue
  @Id
  private Long id;
  @JsonIgnoreProperties( "drivenBy" )
  @StartNode
  private Car car;
  @JsonIgnoreProperties( "drives" )
  @EndNode
  private Person driver;

  public Long getId()
  {
    return this.id;
  }

  public Car getCar()
  {
    return this.car;
  }

  public void setCar( final Car car )
  {
    if( this.car != null && this.car.getDrivenBy() != this )
    {
      this.car.setDrivenBy( null );
    }
    this.car = car;
    if( this.car != null && car.getDrivenBy() != this )
    {
      car.setDrivenBy( this );
    }
  }

  public Person getDriver()
  {
    return this.driver;
  }

  public void setDriver( final Person driver )
  {
    if( this.driver != null && this.driver.getDrives() != this )
    {
      this.driver.setDrives( null );
    }
    this.driver = driver;
    if( this.driver != null && driver.getDrives() != this )
    {
      driver.setDrives( this );
    }
  }
}
